package org.telegram.ui.nebula;
import android.os.*;import android.content.*;import android.widget.*;
/** Local-only privacy preference controls, with truthful capability labels. */
public final class NebulaPrivacyCenterActivity extends NebulaProtectedActivity {
 @Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout root=NebulaToolUi.page(this,"Центр приватності","Ці параметри локальні. Вони НЕ гарантують приховування онлайн, прочитань або переглядів історій у Telegram.");SharedPreferences p=getSharedPreferences("nebula_privacy_v1",0);
 add(root,p,"suppress_typing","Не надсилати звичайний індикатор друкування з відкритого чату (експериментально)");add(root,p,"private_preview","Приховувати текст у локальних попередніх переглядах");add(root,p,"confirm_stories","Нагадувати про приватність перед історіями (планована інтеграція)");add(root,p,"offline_reminder","Нагадування про офлайн (без зміни Telegram-статусу)");add(root,p,"clear_clipboard_warning","Попереджати перед копіюванням у центрі чату");add(root,p,"sensitive_export_warning","Додаткове підтвердження перед експортом (підтримувані екрани)");add(root,p,"lock_on_background","Повторний PIN після виходу з екрана або застосунку");NebulaToolUi.text(this,root,"Захист від скриншотів і PIN налаштовуються окремо. Приховування прочитань, онлайн-статусу та переглядів історій НЕ реалізоване. Приховування друкування охоплює лише один виклик у ChatActivity; інші дії можуть надсилати індикатори.",13,0xffb8abc9);}
 private void add(LinearLayout root,SharedPreferences p,String key,String label){Switch s=new Switch(this);s.setText(label);s.setTextColor(-1);s.setPadding(0,12,0,12);s.setChecked(p.getBoolean(key,false));s.setOnCheckedChangeListener((v,on)->p.edit().putBoolean(key,on).apply());root.addView(s);}
}
